describe('File Download Export Button', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.intercept('GET', '**/api/export/**', {
      statusCode: 200,
      headers: {
        'content-disposition': 'attachment; filename="export.csv"',
        'content-type': 'text/csv'
      },
      body: 'id,name,email\n1,John Doe,john@example.com\n2,Jane Smith,jane@example.com'
    }).as('exportRequest');
  });

  it('should trigger file download when export button is clicked', () => {
    cy.get('[data-testid="export-button"]').should('be.visible').click();

    cy.wait('@exportRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
      expect(interception.response.headers['content-disposition']).to.include('attachment');
      expect(interception.response.headers['content-type']).to.equal('text/csv');
    });

    cy.readFile('cypress/downloads/export.csv', { timeout: 5000 }).should('exist');
  });

  it('should handle export button with query parameters', () => {
    cy.intercept('GET', '**/api/export/**?format=csv&includeHeaders=true', {
      statusCode: 200,
      headers: {
        'content-disposition': 'attachment; filename="export-with-headers.csv"',
        'content-type': 'text/csv'
      },
      body: 'id,name,email,phone\n1,John Doe,john@example.com,555-1234'
    }).as('exportWithParams');

    cy.get('[data-testid="export-button"]').click();

    cy.wait('@exportWithParams').then((interception) => {
      expect(interception.request.url).to.include('format=csv');
      expect(interception.request.url).to.include('includeHeaders=true');
      expect(interception.response.statusCode).to.equal(200);
    });
  });

  it('should display error message when export fails', () => {
    cy.intercept('GET', '**/api/export/**', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('exportError');

    cy.get('[data-testid="export-button"]').click();

    cy.wait('@exportError');
    cy.get('[data-testid="error-message"]').should('be.visible').and('contain', 'Export failed');
  });

  it('should disable export button during download', () => {
    cy.intercept('GET', '**/api/export/**', (req) => {
      req.reply((res) => {
        res.delay(2000);
      });
    }).as('slowExport');

    cy.get('[data-testid="export-button"]').click();
    cy.get('[data-testid="export-button"]').should('be.disabled');

    cy.wait('@slowExport');
    cy.get('[data-testid="export-button"]').should('not.be.disabled');
  });

  it('should support multiple file format exports', () => {
    cy.get('[data-testid="format-selector"]').select('json');

    cy.intercept('GET', '**/api/export/**?format=json', {
      statusCode: 200,
      headers: {
        'content-disposition': 'attachment; filename="export.json"',
        'content-type': 'application/json'
      },
      body: JSON.stringify([{ id: 1, name: 'John Doe' }])
    }).as('jsonExport');

    cy.get('[data-testid="export-button"]').click();

    cy.wait('@jsonExport').then((interception) => {
      expect(interception.response.headers['content-type']).to.equal('application/json');
    });
  });
});
